def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]

# --- Shine-Dalgarno search upstream of each start ---
def rbs_report(start, end, strand, name):
    if strand=='+':
        up = seq[start-21:start-1]     # -20..-1 relative to ATG
        spacer = "fwd %d..%d" % (start-20, start-1)
    else:
        # start codon is at right end of interval (fwd coords)
        up = rc(seq[end:end+20])       # minus-strand sequence 5'->3', 20 nt before ATG
        spacer = "fwd %d..%d" % (end+1, end+20)
    print(name, "upstream 20 nt (5'->3' of gene):", up, " (%s)" % spacer)
    # score purine-rich core
    for motif in ['AGGAGG','GGAGG','AGGAG','AAGGA','AGGA','GGAG']:
        idx = up.find(motif)
        if idx!=-1:
            dist = 20-idx-len(motif)
            print("   motif %s at %d..%d nt before ATG" % (motif, dist, dist+len(motif)-1))
            break
rbs_report(1161,2177,'+','ORF1(+)')
rbs_report(None,953,'-','ORF2(-)')
