# --- Rho-independent terminator: GC-rich palindrome + poly-U run downstream ---
def terminator_scan(s, strand, lo, hi, name):
    print(name)
    reg = seq[lo-1:hi]
    if strand=='-': reg = rc(reg)
    best=None
    for L in range(6,13):
        for i in range(0, len(reg)-2*L):
            a = reg[i:i+L]
            b = reg[i+L:i+2*L]
            # complementary stem? allow palindrome over >70%
            m = sum(1 for x,y in zip(a, rc(b)) if x==y)
            if m >= L-1:  # near-perfect inverted repeat
                tail = reg[i+2*L:i+2*L+8]
                if tail.count('T') >= 5 or tail.count('A') >= 5:
                    if best is None or m>best[0]:
                        best=(m,i,a,b,tail,L)
    if best:
        m,i,a,b,tail,L = best
        fwd_lo = lo+i if strand=='+' else hi-i-2*L+1
        print("   IR stem %s/%s (len %d, %d/8 loop-side match) followed by %s" % (a,b,L,m,tail))
    else:
        print("   no obvious stem-loop+U-run")

