# --- hairpin search allowing 1 mismatch in stem, stem>=6, within 250 bp after each gene's stop ---
def hairpins(sub, label, offset, minstem=6):
    found=[]
    for L in range(12,5,-1):
        for i in range(0, max(0,len(sub)-2*L-2)):
            for lp in range(3,9):
                if i+L+lp+L > len(sub): break
                a=sub[i:i+L]; b=sub[i+L+lp:i+2*L+lp]
                mm=sum(1 for x,y in zip(a,rc(b)) if x!=y)
                if mm<=1:
                    loop=sub[i+L:i+L+lp]
                    tail=sub[i+2*L+lp:min(len(sub),i+2*L+lp+8)]
                    found.append((L,offset+i+1,offset+i+2*L+lp,a,loop,tail,mm))
    # strongest, de-overlapped
    found.sort(key=lambda h:(-h[0],h[6],h[1]))
    keep=[]
    for h in found:
        if any(not(h[1]>e or h[2]<s) for s,e in keep): continue
        keep.append((h[1],h[2]))
        print("  %s: stem %dbp (mismatches %d) at fwd %d-%d | %s---%s---%s | U-tail: %s" % (
            label,h[0],h[6],h[1],h[2],h[3],h[4],rc(h[3]),tail))
    if not keep: print("  %s: none with stem>=6 (<=1 mismatch)" % label)

