import math

STARTS={'ATG','GTG','TTG'}; STOPS={'TAA','TAG','TGA'}
orfs=[]
for strand, s in (('+', seq), ('-', rc(seq))):
    for f in range(3):
        i=f
        while i < len(s)-2:
            if s[i:i+3] in STARTS:
                j=i
                while j < len(s)-2 and s[j:j+3] not in STOPS: j+=3
                if j < len(s)-2:
                    naa=(j-i)//3   # aa excluding stop
                    if naa >= 90:
