    sd = 'GGAGG' in up or 'AGGAGG' in up or 'AAGGA' in up or 'AGGAG' in up or 'GGAGG' in up
    print("%-6d %-11s %-3s %-5s %-5s %-4s GC1/2/3=%.0f/%.0f/%.0f p=%.3g" % (naa, "%d-%d"%(L,R), strand, st, sp, sd, gcs[0],gcs[1],gcs[2],p))

